const GLOBAL = ['New York','San Francisco Bay Area','Dallas','Chicago','Atlanta','Seattle','Austin','Boston','Toronto','London','Dublin','Sydney','Melbourne','Singapore','Dubai','Amsterdam','Berlin','Charlotte','Phoenix','Manchester'];
