const key = (p, t, c) => `${p}|${t}|${c}`.toLowerCase();
const done1 = new Set(), done2 = new Set();
let gDone = 0, iDone = 0;
const isGlobal = c => GLOBAL.map(x => x.toLowerCase()).includes(String(c || '').toLowerCase());
for (const it of $input.all()) {
  const r = it.json || {};
  if (!r.pool) continue;
  const k = key(r.pool, r.title, r.city);
  if (String(r.note || '').toLowerCase().includes('page 2')) done2.add(k); else done1.add(k);
  if (String(r.run_at || '') >= '2026-11-03') { if (isGlobal(r.city)) gDone++; else iDone++; }
}
// baari-baari: is run me India ya duniya (jis taraf kam searches hui ho)
const region = gDone <= iDone ? 'global' : 'india';
const cities = region === 'global' ? GLOBAL : INDIA;
const pools = Object.keys(POOLS).filter(p => !ONLY_POOLS.length || ONLY_POOLS.includes(p));
const all = [];
for (const city of cities) for (let i = 0; i < 12; i++) for (const p of pools) all.push({ pool: p, title: POOLS[p].titles[i], city, region });
let pages = 1;
let picked = all.filter(q => !done1.has(key(q.pool, q.title, q.city))).slice(0, PER_RUN);
if (!picked.length) { pages = 2; picked = all.filter(q => !done2.has(key(q.pool, q.title, q.city))).slice(0, PER_RUN); }
if (!picked.length) return [];
for (const q of picked) q.query = `site:linkedin.com/in "${q.title}" "${q.city}"`;
