let googleResults = 0, profiles = 0;
const seen = new Set();
for (const page of pages) {
  const term = (page.searchQuery && page.searchQuery.term) || '';
  const q = pick.picked.find(p => p.query === term) || pick.picked.find(p => term.includes(p.title) && term.includes(p.city));
  if (!q) continue;
  const P = POOLS[q.pool];
  const qk = `${q.pool}|${q.title}|${q.city}`;
  perQuery[qk] = perQuery[qk] || { results: 0, added: 0 };
  for (const r of page.organicResults || []) {
    googleResults++; perQuery[qk].results++;
    const slug = slugOf(r.url);
    if (!slug) continue;
    profiles++;
    const url = `https://www.linkedin.com/in/${slug}`;
    if (seen.has(url) || existing.has(url) || existing.has(`slug:${slug}`)) { rejected.duplicate++; continue; }
